const fs=require('fs');
const [,,srcPath,outPath]=process.argv;
if(!srcPath||!outPath) throw new Error('USAGE: node patch-match-expanded-outline-20261004.js <src> <out>');
let s=fs.readFileSync(srcPath,'utf8');
const PREV='B46_MATCH_CARD_ACTIVE_DARK_GLOW_20261004';
const MARK='B46_MATCH_EXPANDED_OUTLINE_20261004';
if(!s.includes(PREV)) throw new Error('ACTIVE_DARK_GLOW_BASE_MISSING');
if(s.includes(MARK)) throw new Error('MATCH_EXPANDED_OUTLINE_ALREADY_PRESENT_STOP');
const patch=`\n\n/* ${MARK}: continue the selected-match green edge around its expanded panel without changing geometry. */\nhtml[data-theme="dark"] body .workspace.singlepage .match-row[aria-expanded="true"] + .match-expanded {\n  box-shadow: inset 0 0 0 1px rgba(42,207,131,.34), 0 0 14px rgba(42,207,131,.10) !important;\n}\n`;
s+=patch;
for(const x of [MARK,'.match-row[aria-expanded="true"] + .match-expanded','rgba(42,207,131,.34)','rgba(42,207,131,.10)']) if(!s.includes(x)) throw new Error(`PATCH_VERIFY_MISSING:${x}`);
if(/(?:padding|margin|width|height|border-width|border-style|transform)\s*:/i.test(patch)) throw new Error('GEOMETRY_CHANGE_STOP');
fs.writeFileSync(outPath,s);
console.log(JSON.stringify({ok:true,marker:MARK,inputBytes:Buffer.byteLength(fs.readFileSync(srcPath)),outputBytes:Buffer.byteLength(s)}));
